import{_ as e,c as t,o as i,ah as s}from"./chunks/framework.CKKOjZuE.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"dev_guide/MSQInternals.md","filePath":"dev_guide/MSQInternals.md","lastUpdated":1749487892000}'),o={name:"dev_guide/MSQInternals.md"};function r(n,a,l,d,h,c){return i(),t("div",null,a[0]||(a[0]=[s('<h2 id="msq-files" tabindex="-1">MSQ Files <a class="header-anchor" href="#msq-files" aria-label="Permalink to &quot;MSQ Files&quot;">​</a></h2><p>MSQ Files are the format from which the moseq-reports program reads data including video clips, usage data, transitions data, and other data. Think of it as a word document which requires the Microsoft Word program to access. Should you want to access the data stored in the msq file directly, you can change the extension from <code>.msq</code> to <code>.zip</code> and open it using a file archiver such as 7-Zip.</p><p>Below we describe some of the standard datasets contained in an msq file:</p><h3 id="crowd-movies" tabindex="-1">crowd_movies <a class="header-anchor" href="#crowd-movies" aria-label="Permalink to &quot;crowd_movies&quot;">​</a></h3><p>This folder contains a depth video for each syllable.</p><h3 id="scalars" tabindex="-1">scalars <a class="header-anchor" href="#scalars" aria-label="Permalink to &quot;scalars&quot;">​</a></h3><p>This folder contains data for scalar data with a file for every syllable.</p><h3 id="syllable-clips" tabindex="-1">syllable_clips <a class="header-anchor" href="#syllable-clips" aria-label="Permalink to &quot;syllable_clips&quot;">​</a></h3><p>This folder contains up to 10 examples of each syllable with each example having three movies, one in RGB, one with depth, and one that is a composite of the previous two side by side.</p><h3 id="behavedistances" tabindex="-1">behaveDistances <a class="header-anchor" href="#behavedistances" aria-label="Permalink to &quot;behaveDistances&quot;">​</a></h3><p>Stores the behavior distance metric used to quantify distance.</p><h3 id="groups" tabindex="-1">groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;groups&quot;">​</a></h3><p>A register of the group names.</p><h3 id="individual-transitions" tabindex="-1">individual_transitions <a class="header-anchor" href="#individual-transitions" aria-label="Permalink to &quot;individual_transitions&quot;">​</a></h3><p>An adjacency list of the transitions.</p><h3 id="label-map" tabindex="-1">label_map <a class="header-anchor" href="#label-map" aria-label="Permalink to &quot;label_map&quot;">​</a></h3><p>Stores data for the label map with 0 being the most used for the usage and frame metrics. Maps between raw id, usage regime, and frame regime.</p><h3 id="manifest" tabindex="-1">manifest <a class="header-anchor" href="#manifest" aria-label="Permalink to &quot;manifest&quot;">​</a></h3><p>A file manifest for the .msq file itself.</p><h3 id="samples" tabindex="-1">samples <a class="header-anchor" href="#samples" aria-label="Permalink to &quot;samples&quot;">​</a></h3><p>Columns used to organize sample data.</p><h3 id="spinograam" tabindex="-1">spinograam <a class="header-anchor" href="#spinograam" aria-label="Permalink to &quot;spinograam&quot;">​</a></h3><p>Stores the data for the spinogram with x and y for each time point and up to ten examples for each module.</p><h3 id="usage" tabindex="-1">usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;usage&quot;">​</a></h3><p>Stores data regarding the quantification of usage with a count of the usage frames, how often each module is emitted. The uuid identifies the specific animal.</p>',25)]))}const u=e(o,[["render",r]]);export{m as __pageData,u as default};
